  for (let y = 0; y < 512; y++) {
    for (let x = 0; x < 1024; x++) {
      const n = hash01(x * 374761 + y * 668265);
      const n2 = hash01(x * 127 + y * 8191);
      const v = 38 + n * 16 + n2 * 6;
      const i = (y * 1024 + x) * 4;
      img.data[i] = v + 2;
      img.data[i + 1] = v + 2;
      img.data[i + 2] = v + 1;
      img.data[i + 3] = 255;
    }
  }
  g.putImageData(img, 0, 0);
