function readParams() {
  const num = (id, fallback, min, max) => {
    const v = Number(document.getElementById(id).value);
    if (!Number.isFinite(v)) return fallback;
    return Math.min(max, Math.max(min, v));
  };
  return {
    speed: num('speed', 22, 3, 70),
    mass: num('mass', 1250, 200, 5000),
    columns: Math.round(num('columns', 12, 2, 18)),
    rows: Math.round(num('rows', 8, 2, 14)),
    depth: Math.round(num('depth', 2, 1, 3)),
    brickMass: num('brickMass', 2.5, 0.3, 50),
