    const spot = new THREE.SpotLight(0xfff4d2, 90, 26, 0.55, 0.55, 1.4);
    spot.position.set(0.1, 0.04, zz);
    spot.target.position.set(6, -0.3, zz);
    nose.obj.add(spot);
    nose.obj.add(spot.target);
  }

  const bumperF = addPart('bumperF', 2.07, 0.5, 0, 0.03, 0.12, 0.86, m(BASE_MASS.bumperF), 0.48);
  mesh(bumperF.obj, 0.06, 0.24, 1.72, 0, 0, 0, plastic);
  mesh(bumperF.obj, 0.05, 0.06, 1.2, 0.02, -0.06, 0, trim);

  const bumperR = addPart('bumperR', -2.04, 0.5, 0, 0.06, 0.12, 0.84, m(BASE_MASS.bumperR), 0.48);
  mesh(bumperR.obj, 0.12, 0.24, 1.68, 0, 0, 0, plastic);
  mesh(bumperR.obj, 0.08, 0.06, 0.08, -0.04, -0.02, 0.42, chrome);
  mesh(bumperR.obj, 0.08, 0.06, 0.08, -0.04, -0.02, -0.42, chrome);

  const hood = addPart('hood', 1.28, 0.965, 0, 0.56, 0.02, 0.64, m(BASE_MASS.hood), 0.45);
  mesh(hood.obj, 1.12, 0.04, 1.4, 0, 0, 0, paint);
  mesh(hood.obj, 0.7, 0.012, 0.04, 0.05, 0.026, 0.42, paintDark);
  mesh(hood.obj, 0.7, 0.012, 0.04, 0.05, 0.026, -0.42, paintDark);

  const trunk = addPart('trunk', -1.5, 1.045, 0, 0.36, 0.025, 0.68, m(BASE_MASS.trunk), 0.45);
  mesh(trunk.obj, 0.72, 0.05, 1.36, 0, 0, 0, paint);

  const doors = [];
  const doorSpec = [
    ['FL', 0.4, 0.7, 0.81, 0.36, 0.2],
    ['FR', 0.4, 0.7, -0.81, 0.36, 0.2],
    ['RL', -0.48, 0.68, 0.81, 0.36, 0.18],
    ['RR', -0.48, 0.68, -0.81, 0.36, 0.18]
  ];
  for (const [id, x, y, z, hx, hy] of doorSpec) {
    const d = addPart('door' + id, x, y, z, hx, hy, 0.09, m(BASE_MASS.door), 0.5);
    mesh(d.obj, hx * 2, hy * 2, 0.18, 0, 0, 0, paint);
    mesh(d.obj, 0.04, 0.34, 0.045, -hx + 0.02, 0.26, 0, paint);
    mesh(d.obj, 0.04, 0.34, 0.045, hx - 0.02, 0.26, 0, paint);
    mesh(d.obj, hx * 1.85, 0.04, 0.045, 0, 0.42, 0, paint);
    mesh(d.obj, 0.12, 0.035, 0.03, hx * 0.15, -0.02, Math.sign(z) * 0.1, chrome);
    if (id[0] === 'F') {
      mesh(d.obj, 0.1, 0.08, 0.12, hx * 0.7, 0.16, Math.sign(z) * 0.12, plastic);
      mesh(d.obj, 0.08, 0.06, 0.1, hx * 0.85, 0.22, Math.sign(z) * 0.16, chrome);
    }
    doors.push(d);
  }

  const wheels = [];
  const wheelSpec = [
    ['FL', 1.3, 0.8, bay],
    ['FR', 1.3, -0.8, bay],
    ['RL', -1.35, 0.8, cabin],
    ['RR', -1.35, -0.8, cabin]
  ];
  for (const [id, x, z, host] of wheelSpec) {
    const wx = CAR_X + x;
    const body = makeBody(wx, WHEEL_R, z, params.speed, 0, true);
    body.setAngvel({ x: 0, y: 0, z: -params.speed / WHEEL_R }, true);
    const col = world.createCollider(
      RAPIER.ColliderDesc.cylinder(0.1, WHEEL_R)
        .setRotation(WHEEL_ROT)
        .setMass(m(BASE_MASS.wheel))
        .setFriction(1.15)
        .setRestitution(0.04)
        .setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS)
        .setContactForceEventThreshold(4500),
      body
    );
    tagCollider(col, 'car', body);
    const obj = new THREE.Group();
    buildWheelVisual(obj);
    dynamic.add(obj);
    const rec = { name: 'wheel' + id, body, obj, pos: { x: wx, y: WHEEL_R, z }, host };
    partsByHandle.set(body.handle, rec);
    carBodies.push(body);
    wheelBodies.push(body);
    wheels.push(rec);
  }

  function glassGrid(parent, rows, cols, x0, x1, y0, y1, zSpan, hx, hy, hz, mass) {
    const group = [];
    for (let i = 0; i < rows; i++) {
      for (let j = 0; j < cols; j++) {
        const u = (i + 0.5) / rows;
        const x = x0 + (x1 - x0) * u;
        const y = y0 + (y1 - y0) * u;
        const z = -zSpan + (j + 0.5) * ((2 * zSpan) / cols);
        const rec = addPart('glass', x, y, z, hx, hy, hz, m(mass), 0.18);
        rec.body.setAngularDamping(0.02);
        mesh(rec.obj, Math.max(hx * 2, 0.012), hy * 2 * 0.92, hz * 2 * 0.94, 0, 0, 0, glassMat);
        group.push(rec);
      }
    }
    group.parent = parent;
    group.cols = cols;
    return group;
  }
  function glassSide(parent, x0, x1, y0, y1, z, rows, cols, mass) {
    const group = [];
    const hx = Math.abs(x1 - x0) / cols * 0.4;
    const hy = Math.abs(y1 - y0) / rows * 0.4;
    for (let i = 0; i < rows; i++) {
      for (let j = 0; j < cols; j++) {
        const x = x0 + (x1 - x0) * ((j + 0.5) / cols);
        const y = y0 + (y1 - y0) * ((i + 0.5) / rows);
        const rec = addPart('glass', x, y, z, hx, hy, 0.01, m(mass), 0.18);
        rec.body.setAngularDamping(0.02);
        mesh(rec.obj, hx * 1.84, hy * 1.84, 0.016, 0, 0, 0, glassMat);
        group.push(rec);
      }
    }
    group.parent = parent;
    group.cols = cols;
    return group;
  }

  const wind = glassGrid(cabin, 4, 2, 0.8, 0.52, 1.02, 1.38, 0.62, 0.016, 0.04, 0.28, BASE_MASS.wind);
  const rearG = glassGrid(cabin, 2, 2, -0.98, -1.08, 1.08, 1.3, 0.52, 0.014, 0.048, 0.24, BASE_MASS.rearGlass);
  const sideFL = glassSide(doors[0], 0.12, 0.68, 0.96, 1.1, doors[0].pos.z, 2, 2, BASE_MASS.side);
  const sideFR = glassSide(doors[1], 0.12, 0.68, 0.96, 1.1, doors[1].pos.z, 2, 2, BASE_MASS.side);
  const sideRL = glassSide(doors[2], -0.76, -0.2, 0.94, 1.06, doors[2].pos.z, 2, 2, BASE_MASS.side);
  const sideRR = glassSide(doors[3], -0.76, -0.2, 0.94, 1.06, doors[3].pos.z, 2, 2, BASE_MASS.side);

  weld(bumperF, nose, 14000, false);
  weld(nose, clip, 26000, false);
  weld(clip, bay, 48000, false);
  weld(bay, cabin, 85000, false);
  weld(hood, bay, 16000, false);
  weld(bumperR, cabin, 32000, false);
  weld(trunk, cabin, 72000, false);
  for (const d of doors) weld(d, cabin, 22000, false);
  for (const w of wheels) axle(w.host, w, w.name[5] === 'F' ? 36000 : 150000);

  function linkWindow(group, frameForce) {
    const cols = group.cols;
    const rows = group.length / cols;
    for (let i = 0; i < group.length; i++) {
      weld(group[i], group.parent, frameForce, true);
      const col = i % cols;
      const row = Math.floor(i / cols);
      if (col + 1 < cols) weld(group[i], group[i + 1], frameForce * 0.45, true);
      if (row + 1 < rows) weld(group[i], group[i + cols], frameForce * 0.45, true);
    }
  }
  linkWindow(wind, 6500);
  linkWindow(rearG, 6000);
  linkWindow(sideFL, 4200);
  linkWindow(sideFR, 4200);

  }
  brickMesh.instanceColor.needsUpdate = true;
  brickMesh.instanceMatrix.needsUpdate = true;
}

function buildStaticsPhysics() {
  const ground = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(20, -0.6, 0));
  const gcol = world.createCollider(
    RAPIER.ColliderDesc.cuboid(80, 0.6, 50)
      .setFriction(params.groundFriction)
      .setRestitution(0.03),
    ground
  );
  tagCollider(gcol, 'ground', ground);
  groundBodies.add(ground.handle);

  for (const side of [-1, 1]) {
    const curb = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(TRACK_LEN / 2, 0.05, side * 5.15));
    const cc = world.createCollider(
      RAPIER.ColliderDesc.cuboid(TRACK_LEN / 2, 0.05, 0.18)
        .setFriction(params.groundFriction)
        .setRestitution(0.05),
      curb
    );
    tagCollider(cc, 'ground', curb);
    groundBodies.add(curb.handle);
    const rail = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(TRACK_LEN / 2, 0.48, side * 7.15));
    const rc = world.createCollider(
      RAPIER.ColliderDesc.cuboid(TRACK_LEN / 2, 0.32, 0.08)
        .setFriction(0.6)
        .setRestitution(0.08),
      rail
    );
    tagCollider(rc, 'static', rail);
  }
}

function clearDynamic() {
  while (dynamic.children.length) dynamic.remove(dynamic.children[0]);
  for (const g of geoCache.values()) g.dispose();
  geoCache.clear();
  if (brickMesh) {
    brickMesh.geometry.dispose();
    brickMesh = null;
  }
}

function resetVfx() {
  pLife.fill(0);
  pPos.fill(0);
  vfxRng = mulberry32(0xa11c0de);
  shakeRng = mulberry32(0x51a7e);
  skidAcc = 0;
  skidCount = 0;
  lastSpark = -1;
  lifeAttr.needsUpdate = true;
  pAttr.needsUpdate = true;
}

function buildSim(next) {
  params = next;
  if (eventQueue) eventQueue.free();
  if (world) world.free();
  clearDynamic();
  resetVfx();
  world = new RAPIER.World({ x: 0, y: -params.gravity, z: 0 });
  world.timestep = DT;
  world.numSolverIterations = 10;
  world.numAdditionalFrictionIterations = 4;
  world.numInternalPgsIterations = 2;
  eventQueue = new RAPIER.EventQueue(false);
  carBodies = [];
  wheelBodies = [];
  partsByHandle = new Map();
  colliderInfo = new Map();
  jointsByBody = new Map();
  jointList = [];
  brickBodies = [];
  brickHalf = [];
  groundBodies.clear();
  cabin = null;
  nose = null;
  simTime = 0;
  accumulator = 0;
  impacted = false;
  impactTime = 0;
  settled = false;
  settledTime = 0;
  shake = 0;
  cruise = true;
  userYaw = 0;
  camReady = false;
  buildStaticsPhysics();
  buildWall();
  buildCar();
  placeCamera(0, true);
}

function bodyVec(body, out) {
  const t = body.translation();
  out.set(t.x, t.y, t.z);
  return out;
}
const _a = new THREE.Vector3();
const _b = new THREE.Vector3();
const _look = new THREE.Vector3();
const _dummy = new THREE.Object3D();

function syncGraphics() {
  for (const rec of partsByHandle.values()) {
    const t = rec.body.translation();
    const r = rec.body.rotation();
    rec.obj.position.set(t.x, t.y, t.z);
    rec.obj.quaternion.set(r.x, r.y, r.z, r.w);
  }
  if (!brickMesh) return;
  for (let i = 0; i < brickBodies.length; i++) {
    const t = brickBodies[i].translation();
    const r = brickBodies[i].rotation();
    _dummy.position.set(t.x, t.y, t.z);

    const s = shake * shake;
    camera.position.x += (shakeRng() - 0.5) * 0.22 * s;
    camera.position.y += (shakeRng() - 0.5) * 0.14 * s;
    camera.position.z += (shakeRng() - 0.5) * 0.16 * s;
    shake = Math.max(0, shake - dt * 1.7);
  }
}
let userPitch = 0;

function updateShadows() {
  const cpos = cabin ? bodyVec(cabin.body, _a) : _a.set(12, 0, 0);
  const dist = Math.abs(WALL_FRONT - cpos.x);
  const span = impacted ? 13.5 : Math.min(19, Math.max(11, dist * 0.5 + 6));
  const focusX = (cpos.x + WALL_FRONT) * 0.5;
  sun.position.set(focusX + 15, 27, 11);
  sun.target.position.set(focusX, 0.6, 0);
  sun.target.updateMatrixWorld();
  const sc = sun.shadow.camera;
  sc.left = -span;
  sc.right = span;
  sc.top = span;
  sc.bottom = -span;
  sc.updateProjectionMatrix();
  sun.shadow.camera.updateProjectionMatrix();
}

function loop(now) {
  if (!lastNow) lastNow = now;
  let frameDt = (now - lastNow) / 1000;
  lastNow = now;
  if (frameDt > 0.05) frameDt = 0.05;
  accumulator += frameDt;
  let steps = 0;
  while (accumulator >= DT && steps < 8) {
    stepPhysics();
    accumulator -= DT;
    steps++;
  }
  syncGraphics();
  placeCamera(frameDt, false);
  updateShadows();
  composer.render();
  requestAnimationFrame(loop);
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setSize(window.innerWidth, window.innerHeight);
  ssaoPass.setSize(window.innerWidth, window.innerHeight);
});
renderer.domElement.addEventListener('pointerdown', (e) => {
  if (!settled) return;
  dragging = true;
  dragX = e.clientX;
  dragY = e.clientY;
});
window.addEventListener('pointerup', () => { dragging = false; });
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  userYaw += (e.clientX - dragX) * 0.005;
  userPitch = Math.max(-0.4, Math.min(0.6, userPitch + (e.clientY - dragY) * 0.002));
  dragX = e.clientX;
  dragY = e.clientY;
});
document.getElementById('replay').addEventListener('click', () => {
  lastNow = 0;
  buildSim(readParams());
});
window.addEventListener('keydown', (e) => {
  if (e.key === 'r' || e.key === 'R') {
    if (e.target && e.target.tagName === 'INPUT') return;
    lastNow = 0;
    buildSim(readParams());
  }
});

buildStatic();
await RAPIER.init();

