const meshBuckets = new Map();
function mesh(parent, w, h, d, x, y, z, mat, cast) {
  let map = meshBuckets.get(parent);
  if (!map) {
    map = new Map();
    meshBuckets.set(parent, map);
  }
  let list = map.get(mat);
  if (!list) {
    list = [];
    map.set(mat, list);
  }
  const g = new THREE.BoxGeometry(w, h, d);
  g.translate(x, y, z);
  list.push({ g, cast: !!cast });
}
function flushMeshes() {
  for (const [parent, map] of meshBuckets) {
    for (const [mat, list] of map) {
      const merged = mergeGeometries(list.map((item) => item.g));
      const m = new THREE.Mesh(merged, mat);
      m.castShadow = list.some((item) => item.cast);
      m.receiveShadow = true;
      parent.add(m);
      for (const item of list) item.g.dispose();
    }
  }
  meshBuckets.clear();
}

