function makeBody(worldX, y, z, speed, angDamp, ccd) {
  return world.createRigidBody(
    RAPIER.RigidBodyDesc.dynamic()
      .setTranslation(worldX, y, z)
      .setLinvel(speed, 0, 0)
      .setLinearDamping(0)
      .setAngularDamping(angDamp)
      .setCcdEnabled(ccd)
      .setCanSleep(false)
  );
}
function addBoxCollider(body, hx, hy, hz, mass, friction, threshold, rot) {
  let desc = RAPIER.ColliderDesc.cuboid(hx, hy, hz)
    .setMass(mass)
    .setFriction(friction)
    .setRestitution(0.06)
    .setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS)
    .setContactForceEventThreshold(threshold);
  if (rot) desc = desc.setRotation(rot);
  const col = world.createCollider(desc, body);
  tagCollider(col, 'car', body);

}
const CCD_PARTS = new Set(['frontBay', 'frontClip', 'nose', 'bumperF', 'hood']);
function addPart(name, cx, cy, cz, hx, hy, hz, mass, friction) {
  const wx = CAR_X + cx;
  const body = makeBody(wx, cy, cz, params.speed, 0.06, CCD_PARTS.has(name));
  addBoxCollider(body, hx, hy, hz, mass, friction, 2800);
  const obj = new THREE.Group();
  dynamic.add(obj);
  const rec = { name, body, obj, pos: { x: wx, y: cy, z: cz } };
  partsByHandle.set(body.handle, rec);
  carBodies.push(body);
  if (group) group.obj = obj;
  return rec;
}

