  const postMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(0.1, 0.78, 0.1), railMat, 10);
  const poleMesh = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.08, 0.1, 4.2, 6), railMat, 6);
  const treeMesh = new THREE.InstancedMesh(new THREE.ConeGeometry(1.15, 3.4, 6), treeMat, 8);
  let postI = 0;
  let poleI = 0;
  const dummy = new THREE.Object3D();
  for (const side of [-1, 1]) {
    const gravel = new THREE.Mesh(new THREE.PlaneGeometry(TRACK_LEN, 3.2), gravelMat);
    gravel.rotation.x = -Math.PI / 2;
    gravel.position.set(TRACK_LEN / 2, -0.01, side * 6.5);
    gravel.receiveShadow = true;
    root.add(gravel);

    const curb = new THREE.Mesh(new THREE.BoxGeometry(TRACK_LEN, 0.1, 0.36), curbMat);
    curb.position.set(TRACK_LEN / 2, 0.05, side * 5.15);
    curb.receiveShadow = true;
    root.add(curb);

    for (const y of [0.34, 0.62]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(TRACK_LEN, 0.16, 0.1), railMat);
      rail.position.set(TRACK_LEN / 2, y, side * 7.15);
      rail.receiveShadow = true;
      root.add(rail);
    }
    for (let x = 2; x < TRACK_LEN; x += 8) {
      dummy.position.set(x, 0.39, side * 7.15);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(1, 1, 1);
      dummy.updateMatrix();
      postMesh.setMatrixAt(postI++, dummy.matrix);
    }
    for (const x of [8, 20, 32]) {
      dummy.position.set(x, 2.1, side * 8.1);
      dummy.rotation.set(0, 0, 0);
      dummy.updateMatrix();
      poleMesh.setMatrixAt(poleI++, dummy.matrix);
      const head = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.1, 0.22), lamp);
      head.position.set(x, 4.15, side * 7.75);
      root.add(head);
    }
  }
  postMesh.count = postI;
  poleMesh.count = poleI;
  postMesh.receiveShadow = true;
  poleMesh.receiveShadow = true;
  root.add(postMesh, poleMesh);

  const gantryL = new THREE.Mesh(new THREE.BoxGeometry(0.16, 3.4, 0.16), railMat);
  gantryL.position.set(1.15, 1.7, -4.2);
  root.add(gantryL);
  const gantryR = gantryL.clone();
  gantryR.position.z = 4.2;
  root.add(gantryR);
  const beam = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.16, 8.6), railMat);
  beam.position.set(1.15, 3.35, 0);
  root.add(beam);
  for (const z of [-0.55, 0.55]) {
    const bulb = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.16, 0.16), amber);
    bulb.position.set(1.15, 3.15, z);
    root.add(bulb);
  }

  const hill = new THREE.SphereGeometry(1, 10, 8);
  for (const [x, z, rx, ry] of [[-8, -22, 14, 5], [28, -24, 16, 5.5], [8, 24, 14, 5], [42, 26, 18, 6]]) {
    const h = new THREE.Mesh(hill, hillMat);
    h.scale.set(rx, ry, rx * 0.85);
    h.position.set(x, -1.2, z);
    root.add(h);
  }
  let treeI = 0;
  for (let i = 0; i < 8; i++) {
    const side = i % 2 === 0 ? -1 : 1;
    dummy.position.set(-4 + i * 6, 1.5, side * 12);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    treeMesh.setMatrixAt(treeI++, dummy.matrix);
  }
  treeMesh.count = treeI;
  root.add(treeMesh);

  root.updateMatrixWorld(true);
  root.traverse((obj) => { obj.matrixAutoUpdate = false; });
}

